//! Gold: `page_evidence` is 1:1 with the live `harness/electronics/page_evidence.py`.
//!
//! `tests/fixtures/gold/page_evidence_v1.json` was generated by
//! `scripts/gold_page_evidence.py` — `evidence` cases feed a mock document
//! (page blocks, dict structure, table grids, page rect, OCR results)
//! through `extract_profile_evidence`, kernel cases call `selected_pages`.
//! The PyMuPDF layer is PDF-layer: its outputs travel in the gold exactly as
//! the reference reads them. Each record carries its own `evidence_sha256`
//! over the canonical JSON core — a live differential check against Python's
//! `hashlib`.
//!
//! The cases pin the traps the extractor exists for: `selected_pages` caps
//! each lane's pages while exact pin locations override the cap with BOTH
//! pin lanes (and only `send` locations), tables only on pin/parametric
//! lanes, the layout IR preserving text-layer line geometry and falling back
//! to normalized blocks (and to `visual_blocks` for non-text dict blocks),
//! the OCR chain (`no_text_layer` -> `ocr_fallback`/`no_text_after_ocr`/
//! `ocr_failed` with `Type: message` errors), and
//! `needs_visual_verification` firing only on the three failure statuses.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::page_evidence::{extract_profile_evidence, selected_pages, EvidencePage};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/page_evidence_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

fn page_of(spec: &Value) -> EvidencePage {
    // The generator's mock raises `RuntimeError(message)` for OCR errors;
    // the reference records `f"{type}: {message}"`.
    let ocr_error = spec
        .get("ocr_error")
        .and_then(Value::as_str)
        .map(|m| format!("RuntimeError: {m}"));
    EvidencePage {
        width: spec.get("width").and_then(Value::as_f64).unwrap_or(612.0),
        height: spec.get("height").and_then(Value::as_f64).unwrap_or(792.0),
        blocks: spec
            .get("blocks")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default(),
        dict: if spec
            .get("dict_error")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            None
        } else {
            spec.get("dict").cloned()
        },
        tables: spec.get("tables").and_then(Value::as_array).map(|tables| {
            tables
                .iter()
                .map(|t| {
                    serde_json::json!({
                        "rows": t["rows"],
                        "bbox": t.get("bbox").cloned().unwrap_or(Value::Null),
                    })
                })
                .collect()
        }),
        ocr_blocks: spec.get("ocr_blocks").and_then(Value::as_array).cloned(),
        ocr_error,
    }
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match case["kind"].as_str().unwrap() {
            "evidence" => {
                let input = &case["input"];
                let pages: Vec<EvidencePage> = input["pages"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(page_of)
                    .collect();
                let outcome = extract_profile_evidence(
                    &pages,
                    &input["profile"],
                    input["maximum_pages_per_lane"].as_u64().unwrap() as usize,
                    input
                        .get("enable_ocr_fallback")
                        .and_then(Value::as_bool)
                        .unwrap_or(false),
                    input
                        .get("ocr_language")
                        .and_then(Value::as_str)
                        .unwrap_or("eng"),
                );
                match outcome {
                    Ok(records) => {
                        assert!(
                            case["error"].is_null(),
                            "case {name}: expected error {}",
                            case["error"]
                        );
                        assert_eq!(
                            serde_json::to_value(records).unwrap(),
                            case["expected"],
                            "case {name}"
                        );
                    }
                    Err(error) => {
                        assert_eq!(error, case["error"].as_str().unwrap(), "case {name}");
                    }
                }
            }
            "selected_pages" => {
                let input = &case["input"];
                let outcome = selected_pages(
                    &input["profile"],
                    input["maximum_pages_per_lane"].as_u64().unwrap() as usize,
                );
                let expect = case["expected"].as_object().unwrap();
                if let Some(error) = expect.get("error") {
                    assert_eq!(
                        serde_json::to_value(outcome.err()).unwrap(),
                        serde_json::to_value(Some(error.as_str().unwrap().to_string())).unwrap(),
                        "case {name}"
                    );
                } else {
                    let pages = outcome.unwrap();
                    let mut map = serde_json::Map::new();
                    for (page, lanes) in &pages {
                        map.insert(
                            page.to_string(),
                            serde_json::to_value(lanes.iter().cloned().collect::<Vec<_>>())
                                .unwrap(),
                        );
                    }
                    assert_eq!(Value::Object(map), case["expected"], "case {name}");
                }
            }
            other => panic!("unknown gold case kind {other}"),
        }
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
